func TestRecordError_MarksSpanAsErrored(t *testing.T) {
	t.Parallel()
	ctx := context.Background()

	_, span := Start(ctx, "op")
	testErr := errors.New("something failed")
	span.RecordError(testErr)

	if span.err != testErr {
		t.Errorf("span.err = %v, want %v", span.err, testErr)
	}

	span.End()
}

